export default docs;
declare const docs: "Shows the title of the content item. It is part of the default layout of new pages, and a page normally has exactly one.\n\nThe block stores no data of its own: the text it shows is the content item's `title` field, so change that field to change the title.\n\n### Example\n\n```json\n{ \"@type\": \"title\" }\n```\n";
